362	\section{The projective line and its charts}
363	
364	Let \(A = k[X_0, X_1]\) be the polynomial ring in two variables, graded by total degree. For a
365	homogeneous element \(f \in A\) we write \(A_{(f)}\) for the degree-zero part of the
366	localization \(A_f\); its elements are fractions \(a/f^n\) with \(a\) homogeneous of degree
367	\(n \deg f\).
368	
369	\begin{definition}[The projective line]
370	  \label{def:P1}
371	  \lean{AlgebraicGeometry.P1}
372	  \leanok
373	  The projective line over \(k\) is \(\PP^1 = \Proj A\), the Proj of the graded ring
374	  \(A = k[X_0, X_1]\).
375	\end{definition}
376	
377	\begin{definition}[Degree zero]
378	  \label{def:P1_gradeZero}
379	  \lean{AlgebraicGeometry.P1.gradeZeroAlgEquiv}
380	  \leanok
381	  The inclusion of constants \(k \to A_0\) into the degree-zero part of \(A\) is an
382	  isomorphism of \(k\)-algebras.
383	\end{definition}
384	\begin{proof}
385	  \leanok
386	  It is injective because a nonzero constant polynomial is nonzero, and surjective because a
387	  polynomial which is homogeneous of degree zero is constant.
388	\end{proof}
389	
390	\begin{definition}[Structure morphism]
391	  \label{def:P1_structureMap}
392	  \lean{AlgebraicGeometry.P1.structureMap}
393	  \uses{def:P1, def:P1_gradeZero}
394	  \leanok
395	  The structure morphism \(\PP^1 \to \Spec k\) is the canonical morphism
396	  \(\Proj A \to \Spec A_0\) followed by the isomorphism \(\Spec A_0 \cong \Spec k\) induced by
397	  \ref{def:P1_gradeZero}.
398	\end{definition}
399	
400	\begin{theorem}[Properness of the projective line]
401	  \label{thm:P1_proper}
402	  \lean{AlgebraicGeometry.P1.isProper_structureMap}
403	  \uses{def:P1_structureMap}
404	  \leanok
405	  \(\PP^1\) is proper over \(k\).
406	\end{theorem}
407	\begin{proof}
408	  \leanok
409	  \uses{def:P1_gradeZero}
410	  \(A\) is a finitely generated algebra over its degree-zero part \(A_0 = k\) (generated by
411	  \(X_0\) and \(X_1\)), and the Proj of a graded ring which is finitely generated over its
412	  degree-zero part is proper over the spectrum of the degree-zero part. Composing with the
413	  isomorphism \(\Spec A_0 \cong \Spec k\) preserves properness.
414	\end{proof}
415	
416	\begin{definition}[The projective line as a scheme over \(k\)]
417	  \label{def:P1_asOver}
418	  \lean{AlgebraicGeometry.P1.asOver}
419	  \uses{def:P1_structureMap}
420	  \leanok
421	  \(\PP^1\), regarded as a scheme over \(k\) via the structure morphism of
422	  \ref{def:P1_structureMap}.
423	\end{definition}
424	
425	\begin{definition}[The standard charts]
426	  \label{def:P1_chartOpen}
427	  \lean{AlgebraicGeometry.P1.chartOpen}
428	  \uses{def:P1}
429	  \leanok
430	  For \(i \in \{0,1\}\), the chart \(U_i = D_+(X_i) \subseteq \PP^1\) is the basic open locus
431	  where the homogeneous coordinate \(X_i\) does not vanish.
432	\end{definition}
433	
434	\begin{lemma}[The charts are affine]
435	  \label{lem:P1_chartOpen_affine}
436	  \lean{AlgebraicGeometry.P1.isAffineOpen_chartOpen}
437	  \uses{def:P1_chartOpen}
438	  \leanok
439	  Each chart \(U_i\) is an affine open of \(\PP^1\).
440	\end{lemma}
441	\begin{proof}
442	  \leanok
443	  \(X_i\) is homogeneous of degree \(1 > 0\), and the basic open of \(\Proj\) at a homogeneous
444	  element of positive degree is affine.
445	\end{proof}
446	
447	\begin{lemma}[The charts cover]
448	  \label{lem:P1_chartOpen_sup}
449	  \lean{AlgebraicGeometry.P1.chartOpen_sup}
450	  \uses{def:P1_chartOpen}
451	  \leanok
452	  \(U_0 \cup U_1 = \PP^1\).
453	\end{lemma}
454	\begin{proof}
455	  \leanok
456	  A point of \(\Proj A\) is a homogeneous prime ideal \(\mathfrak p\) of \(A\) not containing
457	  the irrelevant ideal \(A_+\). Every monomial of positive degree is divisible by \(X_0\) or
458	  by \(X_1\), so if both \(X_0 \in \mathfrak p\) and \(X_1 \in \mathfrak p\) then
459	  \(A_+ \subseteq \mathfrak p\), a contradiction. Hence every point avoids some \(X_i\), i.e.\
460	  lies in \(U_0 \cup U_1\).
461	\end{proof}
462	
463	\begin{lemma}[The chart overlap]
464	  \label{lem:P1_chartOpen_inf}
465	  \lean{AlgebraicGeometry.P1.chartOpen_inf}
466	  \uses{def:P1_chartOpen}
467	  \leanok
468	  \(U_0 \cap U_1 = D_+(X_0 X_1)\).
469	\end{lemma}
470	\begin{proof}
471	  \leanok
472	  A homogeneous prime avoids the product \(X_0 X_1\) if and only if it avoids both factors.
473	\end{proof}
474	
475	\begin{definition}[Affine models of the charts]
476	  \label{def:P1_chartIota}
477	  \lean{AlgebraicGeometry.P1.chartι}
478	  \uses{def:P1, def:P1_chartOpen}
479	  \leanok
480	  For \(i \in \{0,1\}\), the canonical morphism \(\Spec A_{(X_i)} \to \PP^1\) associated with
481	  the basic open at the degree-one element \(X_i\); it is an open immersion.
482	\end{definition}
483	
484	\begin{lemma}[Image of the affine model]
485	  \label{lem:P1_chartIota_range}
486	  \lean{AlgebraicGeometry.P1.opensRange_chartι}
487	  \uses{def:P1_chartIota, def:P1_chartOpen}
488	  \leanok
489	  The image of \(\Spec A_{(X_i)} \to \PP^1\) is the chart \(U_i\); thus
490	  \(U_i \cong \Spec A_{(X_i)}\).
491	\end{lemma}
492	\begin{proof}
493	  \leanok
494	  This is the standard description of the basic opens of \(\Proj\): the homogeneous primes
495	  avoiding \(X_i\) correspond to the primes of the degree-zero localization \(A_{(X_i)}\).
496	\end{proof}
497	
498	\begin{lemma}[The affine models lie over \(k\)]
499	  \label{lem:P1_chartIota_structureMap}
500	  \lean{AlgebraicGeometry.P1.chartι_structureMap}
501	  \uses{def:P1_chartIota, def:P1_structureMap}
502	  \leanok
503	  The composite \(\Spec A_{(X_i)} \to \PP^1 \to \Spec k\) is the morphism induced by the
504	  \(k\)-algebra structure of \(A_{(X_i)}\); that is, the affine models are morphisms of
505	  schemes over \(k\).
506	\end{lemma}
507	\begin{proof}
508	  \leanok
509	  \uses{def:P1_gradeZero}
510	  The canonical morphism \(\Proj A \to \Spec A_0\), restricted to the affine chart, is induced
511	  by the ring homomorphism \(A_0 \to A_{(X_i)}\); composing with the isomorphism
512	  \(k \cong A_0\) of \ref{def:P1_gradeZero} gives the claim.
513	\end{proof}
514	
515	\begin{definition}[Chart coordinates]
516	  \label{def:P1_chartCoord}
517	  \lean{AlgebraicGeometry.P1.chartCoord}
518	  \uses{def:P1}
519	  \leanok
520	  For \(i, j \in \{0,1\}\), the chart coordinate is the degree-zero fraction
521	  \(t_{ij} = X_j / X_i \in A_{(X_i)}\).
522	\end{definition}
523	
524	\begin{definition}[Dehomogenization]
525	  \label{def:P1_dehomogenize}
526	  \lean{AlgebraicGeometry.P1.dehomogenize}
527	  \leanok
528	  For \(i \in \{0,1\}\), the dehomogenization at \(X_i\) is the \(k\)-algebra homomorphism
529	  \(\delta_i : k[X_0, X_1] \to k[t]\) with \(\delta_i(X_i) = 1\) and \(\delta_i(X_j) = t\) for
530	  \(j \neq i\).
531	\end{definition}
532	
533	\begin{definition}[From polynomials to the chart ring]
534	  \label{def:P1_polyToAway}
535	  \lean{AlgebraicGeometry.P1.polyToAway}
536	  \uses{def:P1_chartCoord}
537	  \leanok
538	  For \(i, j \in \{0,1\}\), the \(k\)-algebra homomorphism \(k[t] \to A_{(X_i)}\) given by
539	  evaluation at the chart coordinate, \(t \mapsto t_{ij}\).

700	  \leanok
701	  The homomorphism \(\lambda\) of \ref{def:P1_awayToOverlapLeft} identifies
702	  \(A_{(X_0 X_1)}\) with the localization of \(A_{(X_0)}\) at the powers of the chart
703	  coordinate \(t_{01}\).
704	\end{lemma}
705	\begin{proof}
706	  \leanok
707	  This is a general property of degree-zero localizations: for homogeneous elements \(f, g\)
708	  of degree one, \(A_{(fg)}\) is the localization of \(A_{(f)}\) away from the degree-zero
709	  fraction \(g/f\). Here \(f = X_0\), \(g = X_1\) and \(g/f = t_{01}\).
710	\end{proof}
711	
712	\begin{definition}[The overlap identification]
713	  \label{def:P1_overlapAlgEquiv}
714	  \lean{AlgebraicGeometry.P1.overlapAlgEquiv}
715	  \uses{def:P1}
716	  \leanok
717	  The isomorphism of \(k\)-algebras \(\theta : A_{(X_0 X_1)} \cong k[T, T^{-1}]\), with
718	  \(T\) the image of the coordinate \(t_{01}\).
719	\end{definition}
720	\begin{proof}
721	  \leanok
722	  \uses{lem:P1_overlap_isLocalization, def:P1_awayAlgEquiv}
723	  By \ref{lem:P1_overlap_isLocalization}, \(A_{(X_0X_1)}\) is the localization of
724	  \(A_{(X_0)}\) at the powers of \(t_{01}\). The isomorphism
725	  \(\alpha_0 : A_{(X_0)} \cong k[t]\) of \ref{def:P1_awayAlgEquiv} carries \(t_{01}\) to
726	  \(t\), hence induces an isomorphism of the two localizations
727	  \(A_{(X_0X_1)} \cong k[t]_{t} = k[T, T^{-1}]\) (localizations at corresponding
728	  multiplicative sets are canonically isomorphic). The map is \(k\)-linear because
729	  \(\alpha_0\) is.
730	\end{proof}
731	
732	\begin{lemma}[Left restriction is \(t \mapsto T\)]
733	  \label{lem:P1_overlap_res_left}
734	  \lean{AlgebraicGeometry.P1.overlapAlgEquiv_awayToOverlapLeft}
735	  \uses{def:P1_overlapAlgEquiv, def:P1_awayAlgEquiv, def:P1_awayToOverlapLeft}
736	  \leanok
737	  For every \(z \in A_{(X_0)}\) one has \(\theta(\lambda(z)) = p(T)\), where
738	  \(p = \alpha_0(z) \in k[t]\). In other words, under the identifications
739	  \(\alpha_0\) and \(\theta\), the restriction \(\lambda\) is the canonical inclusion
740	  \(k[t] \to k[T, T^{-1}]\), \(t \mapsto T\).
741	\end{lemma}
742	\begin{proof}
743	  \leanok
744	  \uses{lem:P1_overlap_isLocalization}
745	  By construction (\ref{def:P1_overlapAlgEquiv}), \(\theta\) is the comparison of
746	  localizations induced by \(\alpha_0\); under such a comparison the localization map
747	  \(\lambda\) of \ref{lem:P1_overlap_isLocalization} corresponds to the localization map
748	  \(k[t] \to k[T, T^{-1}]\).
749	\end{proof}
750	
751	\begin{lemma}[Right restriction is \(t \mapsto T^{-1}\)]
752	  \label{lem:P1_overlap_res_right}
753	  \lean{AlgebraicGeometry.P1.overlapAlgEquiv_awayToOverlapRight}
754	  \uses{def:P1_overlapAlgEquiv, def:P1_awayAlgEquiv, def:P1_awayToOverlapRight}
755	  \leanok
756	  For every \(z \in A_{(X_1)}\) one has \(\theta(\rho(z)) = q(T^{-1})\), where
757	  \(q = \alpha_1(z) \in k[t]\). In other words, under the identifications \(\alpha_1\) and
758	  \(\theta\), the restriction \(\rho\) is the homomorphism \(k[t] \to k[T, T^{-1}]\),
759	  \(t \mapsto T^{-1}\).
760	\end{lemma}
761	\begin{proof}
762	  \leanok
763	  \uses{lem:P1_coord_mul, lem:P1_overlap_res_left, lem:P1_polyToAway_surjective}
764	  By \ref{lem:P1_overlap_res_left} the image of \(\lambda(t_{01})\) under \(\theta\) is
765	  \(T\), and by \ref{lem:P1_coord_mul} \(\lambda(t_{01})\,\rho(t_{10}) = 1\); applying
766	  \(\theta\) gives \(\theta(\rho(t_{10})) = T^{-1}\). By
767	  \ref{lem:P1_polyToAway_surjective} (for the indices \((1,0)\)) every \(z \in A_{(X_1)}\)
768	  is a polynomial in \(t_{10}\) with coefficients in \(k\); both sides of the claim are
769	  \(k\)-algebra homomorphisms in \(z\), and they agree on \(t_{10}\).
770	\end{proof}
771	
772	\begin{lemma}[Laurent span on the overlap ring]
773	  \label{lem:P1_overlap_span}
774	  \lean{AlgebraicGeometry.P1.exists_awayToOverlap_add}
775	  \uses{def:P1_awayToOverlapLeft, def:P1_awayToOverlapRight}
776	  \leanok
777	  Every \(w \in A_{(X_0 X_1)}\) can be written as \(w = \lambda(z_0) + \rho(z_1)\) with
778	  \(z_0 \in A_{(X_0)}\) and \(z_1 \in A_{(X_1)}\).
779	\end{lemma}
780	\begin{proof}
781	  \leanok
782	  \uses{lem:laurent_span, def:P1_overlapAlgEquiv, lem:P1_overlap_res_left,
783	    lem:P1_overlap_res_right, def:P1_awayAlgEquiv}
784	  Write \(\theta(w) = p(T) + q(T^{-1})\) by \ref{lem:laurent_span} and set
785	  \(z_0 = \alpha_0^{-1}(p)\), \(z_1 = \alpha_1^{-1}(q)\). By
786	  \ref{lem:P1_overlap_res_left} and \ref{lem:P1_overlap_res_right},
787	  \(\theta(\lambda(z_0) + \rho(z_1)) = p(T) + q(T^{-1}) = \theta(w)\), and \(\theta\) is
788	  injective.
789	\end{proof}
