791	\section{Section rings and the Laurent chart pair}
792	
793	\begin{lemma}[The overlap is affine]
794	  \label{lem:P1_overlap_affine}
795	  \lean{AlgebraicGeometry.P1.isAffineOpen_overlap}
796	  \uses{lem:P1_chartOpen_inf}
797	  \leanok
798	  The chart overlap \(U_0 \cap U_1 = D_+(X_0 X_1)\) is an affine open of \(\PP^1\).
799	\end{lemma}
800	\begin{proof}
801	  \leanok
802	  \(X_0 X_1\) is homogeneous of degree \(2 > 0\), and the basic open of \(\Proj\) at a
803	  homogeneous element of positive degree is affine.
804	\end{proof}
805	
806	\begin{definition}[Sections on the left chart]
807	  \label{def:P1_chartSectionsEquiv0}
808	  \lean{AlgebraicGeometry.P1.chartSectionsEquiv₀}
809	  \uses{def:P1_chartOpen, def:P1_chartIota, def:P1_awayAlgEquiv}
810	  \leanok
811	  The ring isomorphism \(\gamma_0 : \Gamma(\PP^1, U_0) \cong k[t]\): the canonical
812	  identification \(\Gamma(\PP^1, D_+(X_0)) \cong A_{(X_0)}\) (sections of \(\Proj\) over a
813	  basic open; equivalently, \(U_0 = \Spec A_{(X_0)}\) via \ref{def:P1_chartIota}) followed by
814	  \(\alpha_0\) of \ref{def:P1_awayAlgEquiv}.
815	\end{definition}
816	
817	\begin{definition}[Sections on the right chart]
818	  \label{def:P1_chartSectionsEquiv1}
819	  \lean{AlgebraicGeometry.P1.chartSectionsEquiv₁}
820	  \uses{def:P1_chartOpen, def:P1_chartIota, def:P1_awayAlgEquiv}
821	  \leanok
822	  The ring isomorphism \(\gamma_1 : \Gamma(\PP^1, U_1) \cong k[t]\), defined as in
823	  \ref{def:P1_chartSectionsEquiv0} with the identification
824	  \(\Gamma(\PP^1, D_+(X_1)) \cong A_{(X_1)}\) followed by \(\alpha_1\).
825	\end{definition}
826	
827	\begin{definition}[Sections on the overlap]
828	  \label{def:P1_overlapSectionsEquiv}
829	  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv}
830	  \uses{lem:P1_chartOpen_inf, def:P1_overlapAlgEquiv}
831	  \leanok
832	  The ring isomorphism \(\gamma_{01} : \Gamma(\PP^1, U_0 \cap U_1) \cong k[T, T^{-1}]\): the
833	  canonical identification \(\Gamma(\PP^1, D_+(X_0X_1)) \cong A_{(X_0X_1)}\) followed by
834	  \(\theta\) of \ref{def:P1_overlapAlgEquiv}.
835	\end{definition}
836	
837	\begin{lemma}[Restriction of sections from the left chart]
838	  \label{lem:P1_res_left}
839	  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv_res_left}
840	  \uses{def:P1_chartSectionsEquiv0, def:P1_overlapSectionsEquiv}
841	  \leanok
842	  For every section \(a \in \Gamma(\PP^1, U_0)\),
843	  \[
844	    \gamma_{01}\bigl(a|_{U_0 \cap U_1}\bigr) = p(T), \qquad p = \gamma_0(a);
845	  \]
846	  under the identifications, restriction from the left chart to the overlap is
847	  \(t \mapsto T\).
848	\end{lemma}
849	\begin{proof}
850	  \leanok
851	  \uses{lem:P1_overlap_res_left}
852	  The identifications \(\Gamma(\PP^1, D_+(f)) \cong A_{(f)}\) are natural with respect to
853	  inclusions of basic opens: restriction of sections from \(D_+(X_0)\) to \(D_+(X_0X_1)\)
854	  corresponds to the ring homomorphism \(\lambda\). Conclude by
855	  \ref{lem:P1_overlap_res_left}.
856	\end{proof}
857	
858	\begin{lemma}[Restriction of sections from the right chart]
859	  \label{lem:P1_res_right}
860	  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv_res_right}
861	  \uses{def:P1_chartSectionsEquiv1, def:P1_overlapSectionsEquiv}
862	  \leanok
863	  For every section \(b \in \Gamma(\PP^1, U_1)\),
864	  \[
865	    \gamma_{01}\bigl(b|_{U_0 \cap U_1}\bigr) = q(T^{-1}), \qquad q = \gamma_1(b);
866	  \]
867	  under the identifications, restriction from the right chart to the overlap is
868	  \(t \mapsto T^{-1}\).
869	\end{lemma}
870	\begin{proof}
871	  \leanok
872	  \uses{lem:P1_overlap_res_right}
873	  As in \ref{lem:P1_res_left}, restriction of sections corresponds to \(\rho\); conclude by
874	  \ref{lem:P1_overlap_res_right}.
875	\end{proof}
